/* 旋转门 */
.carousel {
position:relative;
z-index:1;
overflow:hidden;
}
.carousel > .carousel_scroller {
display:block;
height: 100%;
-webkit-backface-visibility: hidden;
}
.carousel > .carousel_scroller > .carousel_content {
width:100%;
height:100%;
display:block;
float:left;
text-align:left;
}
/* 核心cs_item */
.carousel > .carousel_scroller > .carousel_content .cs_item {
-webkit-box-sizing:border-box;
box-sizing:border-box;
display:block;
float:left;
height:100%;
}

.carousel_page {
width: 400px;
height: 16px;
text-align:center;
}
.carousel_page > li {
display:inline-block;
text-indent:-9999em;
width:16px;
height:16px;
overflow:hidden;
margin-right:10px;
background:url(../img/pop/common_dot.png) 0 -16px no-repeat;
}
.carousel_page > li.active {
background:url(../img/pop/common_dot.png) 0 0 no-repeat;
}

.carousel_page > li:last-child {
    margin:0;
}

.scroller {
    position:relative;
    z-index:1;
    width:100%;
    overflow:auto;
}
.scroller_root {
    display:block;
    height:100%;
    float:left;
    padding:0;
    -webkit-backface-visibility: hidden;
    -webkit-perspective: 1000px;
}
.scroller_content {
    list-style:none;
    display:block;
    float:left;
    width:100%;
    height:100%;
    text-align:left;
}
.scroller_content > li {
    display:block;
    vertical-align:middle;
    float:left;
    width:100px;/* 默认值 */
    height:100%;
}
