@-webkit-keyframes towerpopBounceR2L {
    0% {
        -webkit-transform: translateX(500px);
    }
    
    15% {
        -webkit-transform: translateX(-30px);
    }
    
    20% {
        -webkit-transform: translateX(10px);
    }
    
    25% {
